#!/usr/bin/env node

/**
 * Cleanup Script: Remove temporary files generated by tools
 *
 * This script removes temporary files that accumulate during development:
 * - tmpclaude-*: Claude Code CLI temporary files
 *
 * Usage:
 *   node scripts/cleanup-tmp-files.js
 *   npm run cleanup
 */

const fs = require('fs');
const path = require('path');

const projectRoot = process.cwd();

// Patterns of temporary files to clean up
const tempFilePatterns = [
  /^tmpclaude-.*-cwd$/,
];

let cleanedCount = 0;

function cleanTempFiles(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      // Skip node_modules and .git
      if (entry.name !== 'node_modules' && entry.name !== '.git' && entry.name !== '.next') {
        cleanTempFiles(fullPath);
      }
    } else if (entry.isFile()) {
      // Check if file matches any temp pattern
      for (const pattern of tempFilePatterns) {
        if (pattern.test(entry.name)) {
          try {
            fs.unlinkSync(fullPath);
            console.log(`Removed: ${fullPath}`);
            cleanedCount++;
          } catch (err) {
            console.error(`Failed to remove ${fullPath}:`, err.message);
          }
          break;
        }
      }
    }
  }
}

console.log('🧹 Cleaning temporary files...');
console.log(`Project root: ${projectRoot}\n`);

cleanTempFiles(projectRoot);

console.log(`\n✅ Cleanup complete. Removed ${cleanedCount} temporary file(s).`);
